"""Network settings for all Hugging Face Hub traffic of the nightly sync job."""

import logging

import httpx2
from huggingface_hub import HfApi, set_client_factory
from huggingface_hub.utils._http import hf_request_event_hook

logger = logging.getLogger("app.network")

HUB_TIMEOUT = httpx2.Timeout(60.0, connect=5.0)
JOB_HEADERS = {"X-Acme-Job": "nightly-sync"}


def _apply_timeout(request: httpx2.Request) -> None:
    # HfApi passes `timeout=None` per request, which would disable the client's timeouts:
    # fill every unset component with our default, keep values a caller set explicitly.
    requested = request.extensions.get("timeout") or {}
    defaults = HUB_TIMEOUT.as_dict()
    request.extensions["timeout"] = {
        key: requested.get(key) if requested.get(key) is not None else value for key, value in defaults.items()
    }


def configure_hub_http(transport=None) -> None:
    """Route every huggingface_hub request through one shared, configured HTTP client."""

    def factory() -> httpx2.Client:
        return httpx2.Client(
            transport=transport,
            headers=JOB_HEADERS,
            timeout=HUB_TIMEOUT,
            # Keep huggingface_hub's own hook (offline mode, request ids, debug logging).
            event_hooks={"request": [hf_request_event_hook, _apply_timeout]},
            follow_redirects=True,
        )

    # Closes any existing shared client; the next request creates one from `factory`.
    set_client_factory(factory)


def current_revision(repo_id: str) -> str | None:
    """Commit sha of the model repo's main branch, or None when the Hub cannot be reached."""
    try:
        return HfApi().model_info(repo_id, revision="main").sha
    except (httpx2.ConnectError, httpx2.TimeoutException) as err:
        logger.warning("Could not reach the Hugging Face Hub for %s: %s", repo_id, err)
        return None

